import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@300;400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type KineticSaaSAdProps = Record<string, any>;

const KineticSaaSAd: React.FC<KineticSaaSAdProps> = ({
  backgroundColor = "#F7F5F0",
  transparentBackground = false,
  durationInSeconds = 10,
  
  primaryTextColor = "#2C2A28",
  secondaryTextColor = "#6B655C",
  accentColor = "#E86A33",
  gradientStart = "#F29C38",
  uiPanelColor = "#FFFFFF",
  
  chatNotificationText = "Me to anyone who wants to have a heated conversation with me:",
  hookHeadline = "Perfect.",
  
  buildupLine1 = "Bring the heat — 60°",
  buildupLine2 = "Meet me in the sauna.",
  
  dashboardCardTitle = "45 minutes later...",
  dashboardBenefits = [
    "Best friends again",
    "Too relaxed to care",
    "Detoxed",
    "Hydrated"
  ],
  
  resolutionHeadline1 = "Argue smarter.",
  resolutionHeadline2 = "Not harder.",
  resolutionTagline = "Sauna diplomacy.",
  
  heatGlowIntensity = 0.85,
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global Timings (in frames)
  const tScene1Start = 0;
  const tScene1End = fps * 2.5;
  
  const tScene2Start = fps * 2.0; // Overlaps scene 1 fade out
  const tScene2End = fps * 4.5;
  
  const tScene3Start = fps * 4.2;
  const tScene3End = fps * 7.5;
  
  const tScene4Start = fps * 7.2;

  // --- SCENE 1 LOGIC ---
  const s1ChatSpring = spring({
    frame: frame - (tScene1Start + fps * 0.2),
    fps,
    config: { damping: 14, stiffness: 120 }
  });
  
  const s1HeadlineSpring = spring({
    frame: frame - (tScene1Start + fps * 1.0),
    fps,
    config: { damping: 12, stiffness: 150 }
  });

  const s1Opacity = interpolate(
    frame,
    [tScene1End - fps * 0.5, tScene1End],
    [1, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // --- SCENE 2 LOGIC ---
  const s2Opacity = interpolate(
    frame,
    [tScene2Start, tScene2Start + fps * 0.5, tScene2End - fps * 0.5, tScene2End],
    [0, 1, 1, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const s2Words = buildupLine1.split(" ");
  
  const s2ThermoSpring = spring({
    frame: frame - (tScene2Start + fps * 1.0),
    fps,
    config: { damping: 20, stiffness: 100 }
  });

  const s2Line2Spring = spring({
    frame: frame - (tScene2Start + fps * 1.6),
    fps,
    config: { damping: 16, stiffness: 120 }
  });

  // Global Heat Glow based on Scene 2 & 3
  const heatGlowOpacity = interpolate(
    frame,
    [tScene2Start + fps * 0.5, tScene2Start + fps * 2, tScene4Start, tScene4Start + fps],
    [0, heatGlowIntensity, heatGlowIntensity, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // --- SCENE 3 LOGIC ---
  const s3PanelY = interpolate(
    frame,
    [tScene3Start, tScene3Start + fps * 0.6],
    [height, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  
  const s3Opacity = interpolate(
    frame,
    [tScene3End - fps * 0.5, tScene3End],
    [1, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const s3TitleSpring = spring({
    frame: frame - (tScene3Start + fps * 0.6),
    fps,
    config: { damping: 15 }
  });

  // --- SCENE 4 LOGIC ---
  const s4Opacity = interpolate(
    frame,
    [tScene4Start, tScene4Start + fps * 0.8],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const s4Headline1Spring = spring({
    frame: frame - (tScene4Start + fps * 0.2),
    fps,
    config: { damping: 14, stiffness: 100 }
  });

  const s4Headline2Opacity = interpolate(
    frame,
    [tScene4Start + fps * 1.0, tScene4Start + fps * 1.5],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const s4TaglineSpring = spring({
    frame: frame - (tScene4Start + fps * 1.8),
    fps,
    config: { damping: 14 }
  });

  // Safe Math
  const s = Math.min(width, height);
  const layoutCenter = { display: "flex", flexDirection: "column" as const, justifyContent: "center", alignItems: "center" };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden" }}>
      
      {/* Background Heat Glow Layer */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(circle at 50% 120%, ${gradientStart}88 0%, ${accentColor}00 70%)`,
          opacity: heatGlowOpacity,
          transition: "none",
        }}
      />

      {/* --- SCENE 1: HOOK --- */}
      {frame < tScene1End && (
        <AbsoluteFill style={{ ...layoutCenter, opacity: s1Opacity, transition: "none" }}>
          <div
            style={{
              width: width * 0.8,
              backgroundColor: uiPanelColor,
              padding: "40px",
              borderRadius: "30px",
              boxShadow: "0 20px 40px rgba(0,0,0,0.06)",
              transform: `translateY(${interpolate(s1ChatSpring, [0, 1], [100, 0])}px)`,
              opacity: s1ChatSpring,
              marginBottom: "80px",
              transition: "none",
            }}
          >
            <div style={{ display: "flex", alignItems: "center", marginBottom: "20px" }}>
              <div style={{ width: 20, height: 20, borderRadius: "50%", backgroundColor: accentColor, marginRight: 15 }} />
              <span style={{ fontSize: 32, fontWeight: 600, color: secondaryTextColor }}>Notification</span>
            </div>
            <p style={{ fontSize: 48, fontWeight: 400, color: primaryTextColor, lineHeight: 1.4, margin: 0 }}>
              {chatNotificationText}
            </p>
          </div>

          <h1
            style={{
              fontSize: 140,
              fontWeight: 700,
              color: primaryTextColor,
              letterSpacing: "-0.04em",
              transform: `scale(${interpolate(s1HeadlineSpring, [0, 1], [2.5, 1])})`,
              opacity: s1HeadlineSpring,
              margin: 0,
              transition: "none",
            }}
          >
            {hookHeadline}
          </h1>
        </AbsoluteFill>
      )}

      {/* --- SCENE 2: THE TWIST --- */}
      {frame >= tScene2Start && frame < tScene2End && (
        <AbsoluteFill style={{ ...layoutCenter, opacity: s2Opacity, transition: "none" }}>
          
          {/* Word by word buildup */}
          <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", width: width * 0.8, marginBottom: "60px" }}>
            {s2Words.map((word, i) => {
              const wordSpring = spring({
                frame: frame - (tScene2Start + i * 5),
                fps,
                config: { damping: 12 }
              });
              return (
                <span
                  key={i}
                  style={{
                    fontSize: 72,
                    fontWeight: 600,
                    color: primaryTextColor,
                    marginRight: "20px",
                    transform: `translateY(${interpolate(wordSpring, [0, 1], [40, 0])}px)`,
                    opacity: wordSpring,
                    display: "inline-block",
                    transition: "none",
                  }}
                >
                  {word}
                </span>
              );
            })}
          </div>

          {/* Thermometer UI */}
          <div
            style={{
              width: 120,
              height: 300,
              backgroundColor: `${secondaryTextColor}22`,
              borderRadius: 60,
              padding: 15,
              display: "flex",
              alignItems: "flex-end",
              transform: `scale(${interpolate(s2ThermoSpring, [0, 1], [0.8, 1])})`,
              opacity: s2ThermoSpring,
              transition: "none",
            }}
          >
            <div
              style={{
                width: "100%",
                height: `${s2ThermoSpring * 100}%`,
                background: `linear-gradient(to top, ${accentColor}, ${gradientStart})`,
                borderRadius: 50,
                transition: "none",
              }}
            />
          </div>

          {/* Second Line */}
          <h2
            style={{
              fontSize: 56,
              fontWeight: 400,
              color: secondaryTextColor,
              marginTop: "60px",
              transform: `translateY(${interpolate(s2Line2Spring, [0, 1], [30, 0])}px)`,
              opacity: s2Line2Spring,
              transition: "none",
            }}
          >
            {buildupLine2}
          </h2>

        </AbsoluteFill>
      )}

      {/* --- SCENE 3: TRANSFORMATION --- */}
      {frame >= tScene3Start && frame < tScene3End && (
        <AbsoluteFill
          style={{
            backgroundColor: uiPanelColor,
            transform: `translateY(${s3PanelY}px)`,
            opacity: s3Opacity,
            padding: "10% 8%",
            boxShadow: "0 -20px 60px rgba(0,0,0,0.05)",
            transition: "none",
          }}
        >
          <h3
            style={{
              fontSize: 64,
              fontWeight: 700,
              color: primaryTextColor,
              marginBottom: "80px",
              opacity: s3TitleSpring,
              transform: `translateX(${interpolate(s3TitleSpring, [0, 1], [-50, 0])}px)`,
              transition: "none",
            }}
          >
            {dashboardCardTitle}
          </h3>

          <div style={{ display: "flex", flexDirection: "column", gap: "30px" }}>
            {dashboardBenefits.map((benefit, i) => {
              const itemSpring = spring({
                frame: frame - (tScene3Start + fps * 0.8 + i * 8),
                fps,
                config: { damping: 14 }
              });

              return (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    backgroundColor: backgroundColor,
                    padding: "40px",
                    borderRadius: "24px",
                    transform: `scale(${interpolate(itemSpring, [0, 1], [0.9, 1])}) translateY(${interpolate(itemSpring, [0, 1], [20, 0])}px)`,
                    opacity: itemSpring,
                    transition: "none",
                  }}
                >
                  <div
                    style={{
                      width: 48,
                      height: 48,
                      borderRadius: "50%",
                      backgroundColor: accentColor,
                      display: "flex",
                      justifyContent: "center",
                      alignItems: "center",
                      marginRight: "30px",
                      transform: `scale(${itemSpring})`,
                      transition: "none",
                    }}
                  >
                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round">
                      <polyline points="20 6 9 17 4 12"></polyline>
                    </svg>
                  </div>
                  <span style={{ fontSize: 48, fontWeight: 500, color: primaryTextColor }}>
                    {benefit}
                  </span>
                </div>
              );
            })}
          </div>
        </AbsoluteFill>
      )}

      {/* --- SCENE 4: RESOLUTION --- */}
      {frame >= tScene4Start && (
        <AbsoluteFill style={{ ...layoutCenter, opacity: s4Opacity, transition: "none" }}>
          
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: "20px" }}>
            <h1
              style={{
                fontSize: 100,
                fontWeight: 700,
                color: primaryTextColor,
                margin: 0,
                letterSpacing: "-0.03em",
                transform: `translateY(${interpolate(s4Headline1Spring, [0, 1], [50, 0])}px)`,
                opacity: s4Headline1Spring,
                transition: "none",
              }}
            >
              {resolutionHeadline1}
            </h1>
            
            <h1
              style={{
                fontSize: 100,
                fontWeight: 700,
                color: secondaryTextColor,
                margin: 0,
                letterSpacing: "-0.03em",
                opacity: s4Headline2Opacity,
                transition: "none",
              }}
            >
              {resolutionHeadline2}
            </h1>
          </div>

          <div
            style={{
              marginTop: "80px",
              padding: "20px 40px",
              backgroundColor: `${accentColor}15`,
              border: `2px solid ${accentColor}33`,
              borderRadius: "50px",
              transform: `translateY(${interpolate(s4TaglineSpring, [0, 1], [30, 0])}px)`,
              opacity: s4TaglineSpring,
              transition: "none",
            }}
          >
            <span style={{ fontSize: 36, fontWeight: 600, color: accentColor, textTransform: "uppercase", letterSpacing: "0.05em" }}>
              {resolutionTagline}
            </span>
          </div>

        </AbsoluteFill>
      )}
      
    </AbsoluteFill>
  );
};

export default KineticSaaSAd;